const raw = $input.first().json.body ?? $input.first().json;
const body = typeof raw === 'string' ? JSON.parse(raw) : raw;
const errors = [];
const tenant = String(body.tenant_slug || '').trim();
const leadId = String(body.lead_id || '').trim();
const eventId = String(body.event_id || '').trim();
const eventType = String(body.event_type || '').trim();
const lead = body.lead && typeof body.lead === 'object' ? body.lead : null;

if (tenant !== 'peskids') errors.push('tenant_slug must be peskids');
if (!leadId) errors.push('lead_id is required');
if (!eventId) errors.push('event_id is required');
if (eventType && eventType !== 'lead.created') errors.push('event_type must be lead.created');
if (!lead) {
  errors.push('lead object is required');
} else {
  if (!String(lead.parent_name || '').trim()) errors.push('lead.parent_name is required');
  if (!String(lead.phone || '').trim()) errors.push('lead.phone is required');
  if (!String(lead.email || '').trim()) errors.push('lead.email is required');
}

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const duplicate = Boolean(eventId && staticData.seen[eventId]);
if (!duplicate && errors.length === 0 && eventId) {
  staticData.seen[eventId] = Date.now();
  const keys = Object.keys(staticData.seen);
  if (keys.length > 500) {
    keys.sort((a, b) => (staticData.seen[a] || 0) - (staticData.seen[b] || 0));
    for (let i = 0; i < keys.length - 400; i += 1) delete staticData.seen[keys[i]];
  }
}

return [{
  json: {
    workflow: 'peskids-lead-intake',
    ok: errors.length === 0,
    duplicate,
    tenant_slug: tenant,
    lead_id: leadId,
    event_id: eventId,
    event_type: eventType || 'lead.created',
    source: body.source || 'gohighlevel',
    stage: body.stage || 'New Lead',
    lead,
    automation: body.automation || {},
    next_actions: Array.isArray(body.next_actions) ? body.next_actions : [],
    errors,
    received_at: new Date().toISOString()
  }
}];
